const P = [[9730785733, 933846279, "sv", "Små bekymmer kan växa till större orosmoln i mitt huvud.", "Små bekymmer kan växa till större orosmoln i tankarna."], [9730786041, 933846290, "sv", "Jag övertolkar situationer mer än nödvändigt.", "Jag överanalyserar situationer mer än nödvändigt."], [9730786293, 933846299, "sv", "Musklerna känns ofta spända eller strama.", "Musklerna känns ofta spända eller stela."], [9730786545, 933846308, "sv", "Jag känner mig nervös eller oförmögen att slappna av helt.", "Jag känner mig darrig eller har svårt att slappna av helt."], [9730786741, 933846315, "sv", "Jag känner mig obekväm av att vara i centrum för uppmärksamheten.", "Jag känner mig obekväm med att vara i centrum för uppmärksamheten."], [9730788253, 933846369, "sv", "Jag tenderar att prokrastinera när jag känner mig orolig.", "Jag tenderar att skjuta upp saker när jag känner mig orolig."], [9730791193, 933846474, "sv", "Oönskade tankar dyker upp i mitt sinne, även när jag inte vill det.", "Oönskade tankar dyker upp, även när jag inte vill det."], [9730791277, 933846477, "sv", "Mitt sinne fastnar vid specifika rädslor eller bekymmer.", "Tankarna fastnar vid specifika rädslor eller bekymmer."], [9730791585, 933846488, "sv", "Jag känner mig orolig när vissa tankar kommer in i mitt sinne.", "Jag känner mig orolig när vissa tankar dyker upp."], [9730793209, 933846546, "sv", "Jag litar på mig själv att hantera saker utan att kontrollera.", "Jag litar på att jag kan hantera saker utan att kontrollera dem."], [9730793825, 933846568, "sv", "Jag kan sitta med obehag utan att försöka lösa det.", "Jag kan stå ut med obehag utan att försöka lösa det."], [9730793853, 933846569, "sv", "Jag känner mig driven att utföra mentala handlingar för att känna kontroll.", "Jag känner ett behov av att utföra mentala handlingar för att känna kontroll."], [9730793881, 933846570, "sv", "Jag undviker situationer där jag kan känna mig utan kontroll.", "Jag undviker situationer där jag kan tappa kontrollen."], [9730800769, 933846816, "sv", "Jag känner mig avskild från andras problem.", "Jag känner mig distanserad från andras problem."], [9730801609, 933846846, "sv", "Jag känner mig inte djupt förankrad till de flesta människor.", "Jag känner mig inte djupt knuten till de flesta människor."], [9730803821, 933846925, "sv", "Jag känner mig djupt förankrad i mina känslor.", "Jag har god kontakt med mina känslor."], [9730806817, 933847032, "sv", "Jag hittar lösningar även när informationen är ofullständig.", "Jag finner lösningar även när informationen är ofullständig."]];
