const P0 = $('Payload').first().json; 
const items = P0.items;
const LING = ['daniel@dgmultilingualservices.com','47natcha@gmail.com','therese.svardsten@gmail.com','mteres@terestraducciones.com','sara.guinot.trad@gmail.com'];
const cur = {};
for (const it of $input.all()) { const b = it.json; if (!Array.isArray(b.keys)) throw new Error('no keys array: ' + JSON.stringify(b).slice(0,200));
  for (const k of b.keys) for (const t of (k.translations||[])) cur[t.translation_id] = { v: typeof t.translation === 'object' ? JSON.stringify(t.translation) : t.translation, by: t.modified_by_email }; }
const out = []; const skipped = [];
for (const [tid, kid, iso, oldv, newv] of items) {
  const c = cur[tid];
  if (!c) { skipped.push({ tid, reason: 'not found' }); continue; }
  if (c.v !== oldv) { skipped.push({ tid, reason: 'changed since snapshot', by: c.by, now: c.v }); continue; }
  if (LING.includes(c.by)) { skipped.push({ tid, reason: 'linguist edited', by: c.by }); continue; }
  out.push({ json: { tid, iso, newv, url: 'https://api.lokalise.com/api2/projects/9933660066825e9a8005c8.58526829/translations/' + tid, body: { translation: newv, is_reviewed: false, is_unverified: true } } });
}
if (!out.length) out.push({ json: { skip: true, skipped } });
out[0].json.skipped = skipped;
return out;

const sent = $('Guard').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const ok = [], bad = [];
res.forEach((r, i) => { const s = sent[i]; const t = r.translation || {};
  const v = typeof t.translation === 'object' ? JSON.stringify(t.translation) : t.translation;
  if (v === s.newv && t.is_reviewed === false && t.is_unverified === true) ok.push(s.tid);
  else bad.push({ tid: s.tid, got: JSON.stringify(r).slice(0, 300) }); });
return [{ json: { written: ok.length, ok, bad, skipped: sent[0].skipped || [] } }];
